class Solution:
    def mostPointedTo(self, u: List[str], v: List[str]) -> str:
        deg = {}
        for a, b in zip(u, v):
            deg.setdefault(a, 0); deg[b] = deg.get(b, 0) + 1
        m = max(deg.values())
        return f"{min(x for x in deg if deg[x] == m)} {m}"

